-- v6.99.120 (M1/ETHICS-020) — 11 entità-sblocco + estensioni catene.
-- Generato da scripts/apply_m1_unlock.py — NON editare a mano.
-- Dual-write: JSON = data/entities/batch_37_m1_unlock.json + data/chains/*.
-- Backup pg_dump PRIMA. Applicare con psql -v ON_ERROR_STOP=1.
BEGIN;

-- guard: nessuna delle entità nuove esiste già
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM geo_entities WHERE name_original IN (
    'កម្ពុជា (Longvek-Oudong)', 'សាធារណរដ្ឋខ្មែរ', 'Кнежевина Србија', 'Краљевина Срба, Хрвата и Словенаца', 'إمارة الدرعية', 'إمارة نجد', 'सङ्घीय लोकतान्त्रिक गणतन्त्र नेपाल', 'Mthwakazi'
  )) THEN RAISE EXCEPTION 'entità M1 già presenti — script già applicato?'; END IF;
END $$;

-- ── cambodia_post_angkor ──
                          capital_name, capital_lat, capital_lon, boundary_geojson, boundary_source,
                          confidence_score, status, ethical_notes, wikidata_qid, boundary_geom)
VALUES ('កម្ពុជា (Longvek-Oudong)', 'km', 'kingdom', 1431, 1863,
        'Oudong (ឧដុង្គ)', 11.8239, 104.7425, '{"type": "Polygon","coordinates": [[[103,10.9],[104.5,10.4],[106,10.8],[106.5,12],[106.2,13.4],[105,14.2],[103.2,14],[102.6,13.2],[102.9,12],[103,10.9]]]}', 'historical_approximation',
        0.7, 'confirmed', 'ETHICS-002: The period opened and closed with violence and coercion. Ayutthaya (Siam) sacked the Khmer capital Yasodharapura (Angkor) around 1431, and on 3 January 1594 King Naresuan of Ayutthaya stormed and looted the capital Longvek, deporting much of its population — remembered in Khmer tradition as a national catastrophe. ETHICS-002: The Nguyen lords of Vietnam progressively annexed Kampuchea Krom (the Mekong Delta): in 1698 Nguyen Huu Canh administratively detached Prey Nokor (renamed Sai Gon) from Cambodia, and by 1757 the entire delta was absorbed, leaving the Khmer Krom a dispossessed minority under Vietnamese rule to this day. ETHICS-002: In 1834-1841 Emperor Minh Mang annexed Cambodia outright as the Vietnamese province of Tran Tay, installed Queen Ang Mey as a puppet and imposed forced Vietnamization, until a Khmer rebellion and Siamese intervention restored King Ang Duong under joint Siamese-Vietnamese suzerainty (formalized 1845-1847); Siam separately seized Battambang and Siem Reap provinces in 1794. ETHICS-002: The 11 August 1863 ''protection'' treaty with France was signed by King Norodom under French naval-diplomatic pressure and as an escape from Siamese-Vietnamese domination — a colonial protectorate, not a partnership of equals. ETHICS-001: The primary name is the attested Khmer endonym កម្ពុជា (Kampuchea, attested since the Baksei Chamkrong inscription, 947 CE, and throughout the Middle Period); ''Cambodia'', ''Camboja'' and ''Cambodge'' are European exonyms kept in name_variants. The ''Dark Age'' framing (reflected in the Khmer Wikidata label យុគអន្ធកាលនៃកម្ពុជា) is contested historiography — Vickery and later scholarship show an era of reorientation toward maritime trade, not simple decay.', 'Q4919413',
        ST_Multi(ST_GeomFromGeoJSON('{"type": "Polygon","coordinates": [[[103,10.9],[104.5,10.4],[106,10.8],[106.5,12],[106.2,13.4],[105,14.2],[103.2,14],[102.6,13.2],[102.9,12],[103,10.9]]]}')));

-- ── khmer_republic ──
                          capital_name, capital_lat, capital_lon, boundary_geojson, boundary_source,
                          confidence_score, status, ethical_notes, wikidata_qid, boundary_geom)
VALUES ('សាធារណរដ្ឋខ្មែរ', 'km', 'republic', 1970, 1975,
        'Phnom Penh (ភ្នំពេញ)', 11.5564, 104.9282, '{"type": "Polygon","coordinates": [[[102.35,13.55],[102.75,11.65],[103.55,10.55],[104.45,10.42],[105.35,10.85],[106.2,10.95],[106,11.75],[107.55,12.35],[107.5,14.45],[105.9,14.15],[104.6,14.4],[103.1,14.3],[102.35,13.55]]]}', 'historical_approximation',
        0.85, 'confirmed', 'ETHICS-002: The United States (Nixon administration, US Air Force) bombed the Cambodian countryside in Operations Menu (1969-70) and Freedom Deal (1970 to 15 August 1973), killing an estimated 50,000-150,000 Cambodian civilians per Kiernan and Owen — the toll is disputed, and the underlying tonnage data were themselves revised (c. 2.76 million tons claimed in their 2006 analysis, corrected to roughly 500,000 tons for 1969-73 in their 2015 re-analysis). Shawcross, Chandler and Kiernan all argue the bombing devastated rural society and materially aided Khmer Rouge recruitment. ETHICS-002: In April 1970 the Lon Nol government organized and tolerated pogroms against Cambodia''s c. 400,000-strong ethnic Vietnamese minority: army, police and mobs massacred thousands of civilians, whose bodies floated down the Mekong into South Vietnam, and most of the surviving community fled or was expelled. The Khmer Republic was a US-backed military dictatorship whose 1972 presidential election of Lon Nol was widely regarded as rigged, and which survived only on US military and economic aid until the Khmer Rouge took Phnom Penh on 17 April 1975. ETHICS-001: the primary name is the attested Khmer form សាធារណរដ្ឋខ្មែរ (Sathearonaroat Khmae); the French co-official name République khmère is recorded as a variant. This record fills the 1970-75 gap created by the ETHICS-019 correction, under which the Democratic Kampuchea record (#240) had wrongly carried this state''s name.', 'Q1054184',
        ST_Multi(ST_GeomFromGeoJSON('{"type": "Polygon","coordinates": [[[102.35,13.55],[102.75,11.65],[103.55,10.55],[104.45,10.42],[105.35,10.85],[106.2,10.95],[106,11.75],[107.55,12.35],[107.5,14.45],[105.9,14.15],[104.6,14.4],[103.1,14.3],[102.35,13.55]]]}')));

-- ── serbia_1815_1918 ──
                          capital_name, capital_lat, capital_lon, boundary_geojson, boundary_source,
                          confidence_score, status, ethical_notes, wikidata_qid, boundary_geom)
VALUES ('Кнежевина Србија', 'sr', 'principality', 1815, 1918,
        'Belgrade (Београд)', 44.8176, 20.4569, '{"type": "Polygon","coordinates": [[[19.35,44.9],[19.7,44.77],[20.2,44.66],[20.45,44.82],[20.95,44.67],[21.4,44.78],[21.63,44.66],[22.15,44.47],[22.45,44.67],[22.68,44.55],[22.67,44.21],[22.4,43.85],[22.55,43.45],[23,43.18],[22.55,42.85],[22.35,42.55],[21.7,42.32],[21.45,42.75],[21,43.1],[20.85,43.25],[20.6,43.32],[20.1,43.45],[19.63,43.58],[19.48,43.75],[19.4,43.98],[19.35,44.2],[19.2,44.55],[19.35,44.9]]]}', 'historical_approximation',
        0.9, 'confirmed', 'ETHICS-002-relevant events, perpetrators named. (1) 1862 Belgrade crisis: after the Cukur Fountain killing of a Serb boy by Ottoman soldiers, the Ottoman garrison bombarded civilian Belgrade from the fortress (~50 killed, hundreds of houses damaged) — perpetrator: Ottoman garrison. The subsequent Great-Power Kanlica conference (1862) mandated the removal of the Muslim civilian population from Serbian towns; roughly 10,000 Muslims left the six Serbian garrison towns in the 1862-1867 wave (about 2,100 of them from Belgrade) — a state- and Great-Power-sanctioned population removal benefiting the Serbian state, recorded as ETHNIC_CLEANSING with dual agency (Ottoman bombardment; Serbian/Great-Power removal). (2) 1877-78: during and after the Serbian army''s conquest of the Nis and Toplica sanjaks, the Muslim population — majority Albanian in the countryside, Turkish in towns, roughly one third of the region''s population — was expelled or fled under military pressure; Serbian forces under Prince Milan Obrenovic burned villages and blocked return. Best academic estimates: ~49,000 Albanians among at least 71,000 Muslims (Jagodic 1998; Stefanovic 2005); Albanian historiography cites higher figures. Recorded as ETHNIC_CLEANSING, perpetrator the Serbian army/state. The refugees (muhaxhire) resettled in Kosovo, seeding long-term Serb-Albanian conflict. (3) Balkan Wars 1912-13: Serbian (and Montenegrin) forces conquering Kosovo and Vardar Macedonia committed massacres of Albanian civilians, village burnings and forced conversions, documented contemporaneously by the Carnegie Endowment''s 1914 International Commission report — which found grave violations by ALL belligerents (Serbian, Bulgarian, Greek, Ottoman, Montenegrin); Albanians and Macedonian Slavs passed under Serbian rule without consent, under a regime of military administration. (4) WWI 1914-18: Austria-Hungary invaded (perpetrating documented mass executions of civilians in Macva/Sabac in 1914); the 1915 Central Powers conquest was followed by harsh Austro-Hungarian and Bulgarian occupation regimes (internment, forced Bulgarianization in the east, suppression of the 1917 Toplica uprising with mass reprisals); the winter 1915-16 retreat through Albania killed tens of thousands of soldiers and civilians. Serbia''s total war losses: 16-28% of the pre-war population depending on methodology (~25% is a common mid-range figure) — among the highest per-capita losses of any WWI belligerent. Serbia in this entry is BOTH perpetrator (1862 removals, 1878 expulsions, 1912-13 conquests) and victim (1862 bombardment, 1914-18 invasion and occupation): both are stated without hierarchy.', 'Q684030',
        ST_Multi(ST_GeomFromGeoJSON('{"type": "Polygon","coordinates": [[[19.35,44.9],[19.7,44.77],[20.2,44.66],[20.45,44.82],[20.95,44.67],[21.4,44.78],[21.63,44.66],[22.15,44.47],[22.45,44.67],[22.68,44.55],[22.67,44.21],[22.4,43.85],[22.55,43.45],[23,43.18],[22.55,42.85],[22.35,42.55],[21.7,42.32],[21.45,42.75],[21,43.1],[20.85,43.25],[20.6,43.32],[20.1,43.45],[19.63,43.58],[19.48,43.75],[19.4,43.98],[19.35,44.2],[19.2,44.55],[19.35,44.9]]]}')));

-- ── kingdom_shs_yugoslavia ──
                          capital_name, capital_lat, capital_lon, boundary_geojson, boundary_source,
                          confidence_score, status, ethical_notes, wikidata_qid, boundary_geom)
VALUES ('Краљевина Срба, Хрвата и Словенаца', 'sr', 'kingdom', 1918, 1941,
        'Београд (Belgrade)', 44.8167, 20.4667, '{"type": "Polygon","coordinates": [[[13.9,45.45],[16.5,43.3],[19.35,41.87],[20.55,41.4],[20.98,40.86],[22.93,41.34],[22.98,43.1],[22.68,44.22],[21.2,45.3],[20.1,46.05],[18.9,45.92],[16.4,46.85],[14.45,46.44],[13.9,45.45]]]}', 'historical_approximation',
        0.75, 'confirmed', 'ETHICS-002: Montenegro''s entry into the new state was not a free union: the Podgorica Assembly (24-29 November 1918), convened under Serbian military presence with an irregular electoral procedure, deposed King Nikola I and proclaimed unconditional union with Serbia, and the Greens'' Christmas Uprising (January 1919) was suppressed by the Serbian army and pro-union White militias, with executions, house-burnings and guerrilla fighting into the mid-1920s; Montenegrin historiography (Pavlović 2008) documents this as annexation, Serbian unification historiography as voluntary union — both readings are recorded, not arbitrated. ETHICS-002: On 6 January 1929 King Aleksandar I Karađorđević abolished the constitution, dissolved parliament and banned national and ethnic parties (the 6 January Dictatorship), months after Croat Peasant Party leader Stjepan Radić was fatally shot by a Serb deputy inside the Belgrade parliament (June 1928); the 1929 renaming to Yugoslavia imposed a unitary identity that suppressed Croat, Macedonian and Albanian national expression — Vardar Macedonia was administered as ''South Serbia'' and interwar agrarian colonization settled Serb colonists on lands of Albanians and Turks in Kosovo and Macedonia. ETHICS-002: The state ended through external violence: Nazi Germany, with Italy, Hungary and Bulgaria, invaded on 6 April 1941, opening with the Luftwaffe terror bombing of Belgrade that killed thousands of civilians; after the capitulation of 17 April 1941 the invaders partitioned the country and installed the Ustaša Independent State of Croatia, which carried out genocide against Serbs, Roma and Jews. ETHICS-001: the primary name is the attested founding Serbian-Cyrillic form; the 1918-1920 proclamation form ''Краљевство Срба, Хрвата и Словенаца'' and the 1929 ''Краљевина Југославија'' are recorded as period variants rather than replacing it.', 'Q191077',
        ST_Multi(ST_GeomFromGeoJSON('{"type": "Polygon","coordinates": [[[13.9,45.45],[16.5,43.3],[19.35,41.87],[20.55,41.4],[20.98,40.86],[22.93,41.34],[22.98,43.1],[22.68,44.22],[21.2,45.3],[20.1,46.05],[18.9,45.92],[16.4,46.85],[14.45,46.44],[13.9,45.45]]]}')));

-- ── diriyah_emirate ──
                          capital_name, capital_lat, capital_lon, boundary_geojson, boundary_source,
                          confidence_score, status, ethical_notes, wikidata_qid, boundary_geom)
VALUES ('إمارة الدرعية', 'ar', 'emirate', 1744, 1818,
        'Diriyah (ad-Dirʿiyyah)', 24.7333, 46.5756, '{"type": "Polygon","coordinates": [[[42.5,20.5],[45.5,19.8],[47.5,21.5],[48.5,24.5],[48,26.5],[46.5,27.8],[43.5,27.5],[41.8,25.5],[42,22.5],[42.5,20.5]]]}', 'historical_approximation',
        0.65, 'confirmed', 'ETHICS-002: The state''s expansion was overwhelmingly military and accompanied by explicit religious violence. On 21 April 1802 (date disputed, possibly 1801) roughly 12,000 Wahhabi raiders from Najd, sent under Emir Abdulaziz bin Muhammad Al Saud, sacked the Shia holy city of Karbala in Ottoman Iraq, killed an estimated 2,000-5,000 inhabitants, plundered the shrine of Imam Husayn and destroyed its dome — an atrocity still central to Shia collective memory. In 1803 Saudi forces massacred inhabitants of Taif, and after taking Mecca (1803) and Medina (1804-05) they demolished the venerated tombs of al-Baqi cemetery and Jannat al-Mualla in 1806, destruction condemned across much of the Muslim world. The state itself was destroyed by comparable violence: the Ottoman-Egyptian army of Ibrahim Pasha besieged Diriyah for months in 1818, razed the city in 1819, and beheaded the captured Imam Abdullah bin Saud in Istanbul. ETHICS-001: the primary name is the attested Arabic إمارة الدرعية; "First Saudi State" (الدولة السعودية الأولى) is a retrospective label, and the 2022 Saudi royal decree moving the official founding from the 1744 Wahhabi pact back to Muhammad ibn Saud''s 1727 accession is a politicized modern re-dating that de-emphasizes the state''s Wahhabi origins — both dates are documented here rather than arbitrated. Non-Western historiography is represented via the contemporary Najdi chronicle of Ibn Bishr; Shia accounts of Karbala provide the victims'' perspective against Najdi court chronicles that celebrate the raid.', 'Q146871',
        ST_Multi(ST_GeomFromGeoJSON('{"type": "Polygon","coordinates": [[[42.5,20.5],[45.5,19.8],[47.5,21.5],[48.5,24.5],[48,26.5],[46.5,27.8],[43.5,27.5],[41.8,25.5],[42,22.5],[42.5,20.5]]]}')));

-- ── najd_emirate ──
                          capital_name, capital_lat, capital_lon, boundary_geojson, boundary_source,
                          confidence_score, status, ethical_notes, wikidata_qid, boundary_geom)
VALUES ('إمارة نجد', 'ar', 'emirate', 1824, 1891,
        'Riyadh (الرياض)', 24.6333, 46.7167, '{"type": "Polygon","coordinates": [[[44,20.8],[46.5,20.5],[48.5,21.8],[50.2,24],[50.1,26.6],[48.8,27.3],[46.8,27.2],[43.5,26.8],[43.2,24.5],[43.8,22.3],[44,20.8]]]}', 'historical_approximation',
        0.65, 'confirmed', 'ETHICS-001: The primary name Imarat Najd (Emirate of Najd) is the attested contemporary designation; "Second Saudi State" (al-Dawla al-Su''udiyya al-Thaniya) is a retrospective label of modern Saudi historiography and is kept as a variant, not the primary name. ETHICS-002: The state was founded and ended by military violence, perpetrators named: Turki ibn Abdullah''s forces besieged and expelled the Egyptian garrison of Muhammad Ali''s occupation army from Riyadh in 1824, six years after Ibrahim Pasha''s Ottoman-Egyptian army razed Diriyah (1818) and had Imam Abdullah bin Saud executed in Istanbul. ETHICS-002: The 1830 reconquest of al-Hasa and Qatif placed the region''s large Twelver Shia population under a Wahhabi-legitimated state that treated them as tributary subjects with discriminatory taxation. Dynastic violence was chronic and is stated plainly: Turki was assassinated in 1834 by his cousin Mishari bin Abdul Rahman (executed in turn by Faisal bin Turki); Egypt''s Khurshid Pasha re-invaded in 1838, deporting Imam Faisal to Cairo and installing Khalid bin Saud as vassal until Faisal''s return in 1843. After Faisal''s death (1865) the fratricidal civil war between his sons Abdullah and Saud devastated Najd, and Abdullah''s 1871 appeal to Ottoman governor Midhat Pasha ended in betrayal — the Ottomans annexed al-Hasa for themselves instead of helping him. The state was destroyed at the Battle of Mulayda (21 January 1891) by Muhammad bin Abdullah Al Rashid of Jabal Shammar, and the Al Saud under Abdul Rahman bin Faisal fled into exile in Kuwait. Non-Western historiography is foregrounded via the contemporary Najdi chronicle of Ibn Bishr.', 'Q146862',
        ST_Multi(ST_GeomFromGeoJSON('{"type": "Polygon","coordinates": [[[44,20.8],[46.5,20.5],[48.5,21.8],[50.2,24],[50.1,26.6],[48.8,27.3],[46.8,27.2],[43.5,26.8],[43.2,24.5],[43.8,22.3],[44,20.8]]]}')));

-- ── nepal_republic ──
                          capital_name, capital_lat, capital_lon, boundary_geojson, boundary_source,
                          confidence_score, status, ethical_notes, wikidata_qid, boundary_geom)
VALUES ('सङ्घीय लोकतान्त्रिक गणतन्त्र नेपाल', 'ne', 'republic', 2008, NULL,
        'Kathmandu (काठमाडौँ)', 27.7172, 85.324, '{"type": "Polygon","coordinates": [[[80.1,28.7],[81.6,28.1],[83,27.4],[85,26.9],[86.5,26.55],[88.15,26.4],[88.2,27.1],[88,27.9],[86.5,28.1],[84.2,29.3],[82.2,30.2],[80.4,29.9],[80.1,28.7]]]}', 'historical_approximation',
        0.85, 'confirmed', 'ETHICS-002: The republic was born from the 1996-2006 civil war launched by the Communist Party of Nepal (Maoist) against the Kingdom of Nepal: approximately 13,000 deaths documented by OHCHR (Nepal Conflict Report, 2012), with Nepal government figures reaching ~17,000; INSEC data attribute the majority of documented killings to state security forces (Royal Nepal Army and police, 8,200+ killed 1996-2005) versus 4,000+ killed by the Maoists — both perpetrators named explicitly. ETHICS-002: Over 1,300 people were forcibly disappeared during the war, most by state forces, with Tharu victims of Bardiya district grossly overrepresented; transitional justice (TRC and Commission on Enforced Disappearances) has delivered near-total impunity to date. ETHICS-002: During the September 2015 constitution promulgation, more than 50 people died in the Terai unrest overall (Aug 2015-Feb 2016) - protesters, mostly Madhesi and Tharu, killed by police, and at least 9 police killed by protesters; Human Rights Watch (''Like We Are Not Nepali'', 2015) documented unlawful killings on both sides including excessive police force; no senior official held accountable, and the subsequent 135-day border blockade (Madhesi groups, partially supported by India) caused a humanitarian fuel and medicine crisis. ETHICS-003: Madhesi, Tharu, Janajati and Dalit communities contest the 2015 federal province boundaries and citizenship clauses as perpetuating historic domination by hill high-caste (Khas Arya) elites; this record documents the dispute without arbitrating it. ETHICS-001: the primary name is the attested Nepali Devanagari form; note the 2015 Constitution (Art. 4) formally names the state simply ''Nepal'', while the full republican formula remains in official and international use since 2008. ETHICS-003: the Kalapani-Lipulekh-Limpiyadhura territory (~335-372 km2) is claimed by Nepal (2020 constitutional map amendment) but administered by India — both versions are noted, neither endorsed.', 'Q837',
        ST_Multi(ST_GeomFromGeoJSON('{"type": "Polygon","coordinates": [[[80.1,28.7],[81.6,28.1],[83,27.4],[85,26.9],[86.5,26.55],[88.15,26.4],[88.2,27.1],[88,27.9],[86.5,28.1],[84.2,29.3],[82.2,30.2],[80.4,29.9],[80.1,28.7]]]}')));

-- ── ndebele_kingdom ──
                          capital_name, capital_lat, capital_lon, boundary_geojson, boundary_source,
                          confidence_score, status, ethical_notes, wikidata_qid, boundary_geom)
VALUES ('Mthwakazi', 'nd', 'kingdom', 1838, 1893,
        'koBulawayo', -20.3023, 28.6264, '{"type": "Polygon","coordinates": [[[27.2,-21.5],[28.5,-21.8],[29.8,-21],[30,-20],[29.5,-19],[28.5,-18.5],[27,-19],[26.5,-20.3],[27.2,-21.5]]]}', 'historical_approximation',
        0.65, 'confirmed', 'ETHICS-002: The kingdom was destroyed by Cecil Rhodes''s British South Africa Company in the First Matabele War (October 1893 - January 1894): company Maxim guns, used here in battle for the first time, killed roughly 1,500 Ndebele at the Shangani (25 Oct 1893) and about 2,500 at Bembesi (1 Nov 1893) against single-digit company battle deaths; koBulawayo was occupied on 4 November 1893, Lobengula died in flight in January 1894, and the company''s Victoria Agreement ''loot'' terms promised each volunteer about 6,000 acres of seized Ndebele land plus a share of confiscated cattle. ETHICS-002: The 1888 Rudd Concession was obtained by deception - missionary interpreter Charles Helm mistranslated the text, and the verbal assurances given to Lobengula (no more than ten diggers, subject to Ndebele law) were deliberately omitted from the written English version; Lobengula repudiated the concession and protested to Queen Victoria, and was ignored, while Rhodes used it to secure the BSAC royal charter in 1889. ETHICS-002: The Ndebele state itself was built by conquest: Mzilikazi''s forces subjugated the Rozvi remnants (c. 1838-1840) and extracted tribute, cattle and captives from western Shona and Kalanga communities, incorporated at the bottom of a three-tier status hierarchy (abeZansi, abeNhla, amaHole). ETHICS-003: the ''predatory raiding state'' image is contested - Julian Cobbing and Zimbabwean historians such as Ndlovu-Gatsheni argue it was inflated by BSAC propaganda to justify the 1893 invasion, and this record reports both the violence and the dispute. ETHICS-001: the primary name Mthwakazi is the attested endonym; ''Matabele'' is a Sotho-Tswana-mediated exonym adopted by the British and kept only as a variant.', 'Q1193853',
        ST_Multi(ST_GeomFromGeoJSON('{"type": "Polygon","coordinates": [[[27.2,-21.5],[28.5,-21.8],[29.8,-21],[30,-20],[29.5,-19],[28.5,-18.5],[27,-19],[26.5,-20.3],[27.2,-21.5]]]}')));

