WHERE chain_id = 124 AND sequence_order = 1 AND entity_id = 364 AND transition_type IS NULL;

UPDATE chain_links SET sequence_order = sequence_order + 1 WHERE chain_id = 125;
VALUES (125, 128, 0, NULL, NULL, false, 'Lan Xang (1354-1707), the unified Lao kingdom of the middle Mekong founded by Fa Ngum with Khmer military backing; capitals Luang Prabang (1354-1560) and Vientiane (1560-1707); partitioned in 1707 after the succession crisis that followed Sourigna Vongsa''s death (1694).', NULL);
UPDATE chain_links SET transition_year = 1713, transition_type = 'PARTITION', is_violent = false, ethical_notes = 'Champasak separated from the Vientiane sphere in 1713 after a southern secession, completing the three-way division of Lan Xang.'
WHERE chain_id = 125 AND sequence_order = 1 AND entity_id = 363 AND transition_type IS NULL;

UPDATE dynasty_chains SET name = 'Lan Xang partition — Vientiane line: ອານາຈັກລ້ານຊ້າງ → ອານາຈັກວຽງຈັນ → Siam' WHERE id = 123;
UPDATE dynasty_chains SET name = 'Lan Xang partition — Luang Prabang line: ອານາຈັກລ້ານຊ້າງ → ອານາຈັກຫລວງພະບາງ → French Indochina' WHERE id = 124;
UPDATE dynasty_chains SET name = 'Lan Xang partition — Champasak line: ອານາຈັກລ້ານຊ້າງ → ອານາຈັກຈຳປາສັກ → French Indochina' WHERE id = 125;

-- ── catena cambogiana 126: prepend Khmer Empire (#19) + post-Angkor ──
UPDATE chain_links SET sequence_order = sequence_order + 2 WHERE chain_id = 126;
VALUES (126, 19, 0, NULL, NULL, false, 'The Khmer Empire (802-1431), the Angkorian state whose capital Yasodharapura was the region''s hegemon for six centuries.', 'Also heads the Thai/Khmer Southeast Asian trunk chain; both successions are real (Ayutthaya absorbed much of the empire''s west; the Khmer royal line continued south-east).');
VALUES (126, (SELECT id FROM geo_entities WHERE name_original = 'កម្ពុជា (Longvek-Oudong)'), 1, 1431, 'SUCCESSION', true, 'After Ayutthaya sacked Yasodharapura/Angkor (~1431), the Khmer court relocated south-east (Chaktomuk, then Longvek, then Oudong): the same royal polity relocated, not a new state - typed SUCCESSION with is_violent=true because the trigger was the Ayutthayan conquest.', 'Perpetrator of the 1431 sack named: Ayutthaya (Siam). Longvek fell to Naresuan of Ayutthaya on 3 January 1594 with mass deportations - see the entity record.');
UPDATE chain_links SET transition_year = 1863, transition_type = 'ANNEXATION', is_violent = false WHERE chain_id = 126 AND sequence_order = 2 AND entity_id = 261 AND transition_type IS NULL;
UPDATE dynasty_chains SET name = 'Cambodian state: អាណាចក្រខ្មែរ → កម្ពុជា (Longvek-Oudong) → Indochine française → Kingdom of Cambodia' WHERE id = 126;

-- ── catena serba 34: append Србија → СХС → СФРЈ ──
VALUES (34, (SELECT id FROM geo_entities WHERE name_original = 'Кнежевина Србија'), 4, 1815, 'DECOLONIZATION', true, 'Serbian self-rule re-emerged from the Ottoman Empire through the uprisings of 1804-1815: de facto autonomy from the Second Uprising settlement (1815), hereditary autonomous principality by hatt-i sharif (1830), full international independence at the Treaty of Berlin (1878), kingdom from 1882.', 'The transition was a violent decolonization (two uprisings, 1804-13 and 1815). ETHICS-002: the consolidating Serbian state was also a perpetrator - the 1862-67 removal of the Muslim population from the garrison towns and the 1878 expulsions from the Nis/Toplica sanjaks (~49,000 Albanians among at least 71,000 Muslims) are recorded on the entity.');
VALUES (34, (SELECT id FROM geo_entities WHERE name_original = 'Краљевина Срба, Хрвата и Словенаца'), 5, 1918, 'UNIFICATION', false, 'On 1 December 1918 the Kingdom of Serbia merged with the State of Slovenes, Croats and Serbs (and, via the contested Podgorica Assembly, with Montenegro) into the Kingdom of Serbs, Croats and Slovenes, renamed Yugoslavia in 1929.', 'The Serbia-side unification was negotiated and peaceful; the Montenegrin absorption was contested and its aftermath violent (Christmas Uprising 1919) - see the Montenegrin chain, where that link is typed ANNEXATION.');
VALUES (34, 231, 6, 1945, 'REVOLUTION', true, 'The Axis invasion (April 1941) destroyed the kingdom; after four years of occupation, partition, genocide (NDH camps, Jasenovac) and multi-sided war, the communist Partisans established the Federal People''s Republic (AVNOJ 1943; monarchy abolished 29 November 1945).', 'The 1941-45 period saw occupation, the Holocaust and the Ustasa genocide of Serbs, Roma and Jews, and civil war among resistance movements - the socialist state emerged from that violence, not from a peaceful succession.');
UPDATE dynasty_chains SET name = 'Serbian state trunk: Raska → Srpsko Carstvo → Српска деспотовина → Ottoman → Кнежевина Србија → Југославија (СХС → СФРЈ)' WHERE id = 34;

-- ── catena montenegrina 130: append СХС ──
VALUES (130, (SELECT id FROM geo_entities WHERE name_original = 'Краљевина Срба, Хрвата и Словенаца'), 2, 1918, 'ANNEXATION', true, 'With King Nikola I in exile and the country under Serbian military occupation, the Podgorica Assembly (24-29 November 1918), elected under conditions controlled by unionist forces, deposed the king and declared unconditional union with Serbia; the Greens'' Christmas Uprising (January 1919, Cetinje) was suppressed by the Serbian army and pro-union militias, with guerrilla resistance into the mid-1920s.', 'Montenegrin historiography (Pavlović, ''Balkan Anschluss'') reads the union as annexation; Serbian unionist historiography as voluntary unification - both readings recorded, not arbitrated (no-single-version principle). Typed ANNEXATION with is_violent=true for the armed suppression that followed.');
UPDATE dynasty_chains SET name = 'Montenegrin state: Зета → Црна Гора → Краљевина СХС' WHERE id = 130;

-- ── 3 catene NUOVE ──
VALUES ('Saudi dynastic states: إمارة الدرعية → إمارة نجد → المملكة العربية السعودية', 'en', 'DYNASTY', 'Arabian Peninsula / Najd', 'The three Saudi-Wahhabi states of the Al Saud: the Emirate of Diriyah (1744-1818, destroyed by the Ottoman-Egyptian expedition), the Emirate of Najd (1824-1891, ended by the Rashidi conquest at Mulayda), and the Kingdom of Saudi Arabia (proclaimed 1932 after Ibn Saud''s 1902-1932 reconquest and unification).', 0.8, 'confirmed', 'ETHICS-002: every transition in this chain is violent and is recorded as such. The chain is DYNASTIC (same Al Saud house), not an unbroken state: two interregna (1818-1824 under Egyptian occupation after Ibrahim Pasha razed Diriyah and had Imam Abdullah bin Saud executed; 1891-1902 under Rashidi rule with the Al Saud exiled in Kuwait) are documented on the links, not papered over. The third state''s unification was by conquest: Riyadh 1902, Ha''il 1921, the Hejaz 1924-25 (including the Ta''if massacre of 1924, ~300-400 civilians killed by the Ikhwan) - per the cross-check, the 1932 transition is typed UNIFICATION (conquest-built), not ''restoration''. The state-sponsored 2022 re-dating of the first state''s founding to 1727 is treated as politicized periodization (see the Diriyah entity record).', '[{"citation": "Madawi Al-Rasheed, A History of Saudi Arabia, Cambridge University Press, 2002 (2nd ed. 2010)", "url": null, "source_type": "academic"}, {"citation": "Alexei Vassiliev, The History of Saudi Arabia, Saqi Books, 1998", "url": null, "source_type": "academic"}, {"citation": "R. Bayly Winder, Saudi Arabia in the Nineteenth Century, Macmillan, 1965", "url": null, "source_type": "academic"}]');
VALUES ((SELECT id FROM dynasty_chains WHERE name = 'Saudi dynastic states: إمارة الدرعية → إمارة نجد → المملكة العربية السعودية'), (SELECT id FROM geo_entities WHERE name_original = 'إمارة الدرعية'), 0, NULL, NULL, false, 'The first Saudi state: the 1744 pact between Muhammad ibn Saud and Muhammad ibn Abd al-Wahhab turned the Diriyah town emirate into an expansionist religious-political state that conquered Najd, al-Hasa and the Hejaz.', NULL);
VALUES ((SELECT id FROM dynasty_chains WHERE name = 'Saudi dynastic states: إمارة الدرعية → إمارة نجد → المملكة العربية السعودية'), (SELECT id FROM geo_entities WHERE name_original = 'إمارة نجد'), 1, 1824, 'RESTORATION', true, 'Al Saud restoration after a six-year interregnum (1818-1824): Ibrahim Pasha''s Ottoman-Egyptian army had razed Diriyah (1818) and executed Imam Abdullah bin Saud in Istanbul; in 1824 Turki ibn Abdullah retook Riyadh from the Egyptian garrison by siege and made it the new capital.', 'The 1818-1824 gap (Egyptian occupation, failed risings of Mishari bin Saud 1819-20 and Turki 1821-23) is real and documented - the chain records a dynastic restoration, not state continuity.');
VALUES ((SELECT id FROM dynasty_chains WHERE name = 'Saudi dynastic states: إمارة الدرعية → إمارة نجد → المملكة العربية السعودية'), 253, 2, 1932, 'UNIFICATION', true, 'After the Rashidi conquest of Najd (Mulayda 1891) and Al Saud exile in Kuwait, Abdulaziz Ibn Saud retook Riyadh in 1902 and unified the peninsula by conquest over three decades: Ha''il and the Rashidi emirate (1921), the Hejaz (1924-25), proclamation of the Kingdom of Saudi Arabia on 23 September 1932.', 'Typed UNIFICATION (not ''restoration'') per cross-check: the third state was conquest-built. The conquest of the Hejaz included the Ta''if massacre (September 1924, ~300-400 civilians killed by the Ikhwan); the Ikhwan themselves were crushed by Ibn Saud at Sabilla (1929) when they pressed to continue raiding.');

VALUES ('Nepalese state: गोर्खा राज्य → सङ्घीय लोकतान्त्रिक गणतन्त्र नेपाल', 'en', 'SUCCESSION', 'South Asia / Himalaya', 'The Nepalese state from the Gorkha conquest-founded Shah kingdom (1768) to the Federal Democratic Republic declared on 28 May 2008 by the 1st Constituent Assembly, which abolished the 240-year monarchy.', 0.9, 'confirmed', 'ETHICS-002: the 2008 transition is typed REVOLUTION with is_violent=true - the abolition vote itself (560-4) was peaceful and King Gyanendra left the palace without resistance, but the republic was the direct outcome of the 1996-2006 civil war (~13,000 deaths documented by OHCHR, Nepali government figures to ~17,000; the majority of documented killings attributed to state security forces per INSEC) and of the April 2006 Jana Andolan II uprising (~18-25 protesters killed by royal security forces). Marking it non-violent would erase the war that produced it.', '[{"citation": "John Whelpton, A History of Nepal, Cambridge University Press, 2005", "url": null, "source_type": "academic"}, {"citation": "OHCHR, Nepal Conflict Report, 2012", "url": "https://www.ohchr.org/en/documents/reports/nepal-conflict-report", "source_type": "primary"}, {"citation": "Sebastian von Einsiedel, David M. Malone, Suman Pradhan (eds.), Nepal in Transition: From People''s War to Fragile Peace, Cambridge University Press, 2012", "url": null, "source_type": "academic"}]');
VALUES ((SELECT id FROM dynasty_chains WHERE name = 'Nepalese state: गोर्खा राज्य → सङ्घीय लोकतान्त्रिक गणतन्त्र नेपाल'), 399, 0, NULL, NULL, false, 'The Shah kingdom founded by Prithvi Narayan Shah''s conquest of the Kathmandu valley (1768-69), expanded through the Anglo-Nepalese war (1814-16, Sugauli treaty), ruled 1846-1951 by the hereditary Rana premiership, and ended by the 2006-08 peace process.', NULL);
VALUES ((SELECT id FROM dynasty_chains WHERE name = 'Nepalese state: गोर्खा राज्य → सङ्घीय लोकतान्त्रिक गणतन्त्र नेपाल'), (SELECT id FROM geo_entities WHERE name_original = 'सङ्घीय लोकतान्त्रिक गणतन्त्र नेपाल'), 1, 2008, 'REVOLUTION', true, 'On 28 May 2008 the newly elected Constituent Assembly abolished the monarchy (560-4) and declared a federal democratic republic; Gyanendra Shah left Narayanhiti palace peacefully on 11 June 2008.', 'is_violent=true refers to the revolutionary process (1996-2006 people''s war, ~13,000-17,000 dead; 2006 Jana Andolan II), not to the final vote, which was peaceful - see chain-level note.');

VALUES ('Taqali and the Mahdiyya: مملكة تقلي → الدولة المهدية', 'en', 'SUCCESSION', 'Northeast Africa / Sudan (Nuba mountains)', 'The Nuba-mountains kingdom of Taqali, independent for over three centuries, conquered by the Mahdist state: invaded from 1883, its ruler Makk Adam captured in July 1884 (he died in Mahdist captivity); the Mahdiyya itself was destroyed by the British-led Anglo-Egyptian reconquest in 1898-99.', 0.7, 'confirmed', 'ETHICS-002: the transition is a violent conquest and is recorded as such. Taqali''s resistance in the hills was never fully broken - Mahdist control of the Nuba mountains remained contested, and a Taqali lineage re-emerged as a client under the Anglo-Egyptian Condominium; the chain records the 1884 destruction of the independent kingdom, not a total erasure of the Taqali polity''s people. The successor''s own end (Omdurman 1898, ~10,000-12,000 Sudanese dead to Maxim guns and artillery against 48 British-led casualties; Condominium agreement 1899) is colonial violence, perpetrator named on the Mahdist entity record.', '[{"citation": "Janet J. Ewald, Soldiers, Traders, and Slaves: State Formation and Economic Transformation in the Greater Nile Valley, 1700-1885, University of Wisconsin Press, 1990", "url": null, "source_type": "academic"}, {"citation": "P. M. Holt, The Mahdist State in the Sudan, 1881-1898, 2nd ed., Clarendon Press, 1970", "url": null, "source_type": "academic"}]');
VALUES ((SELECT id FROM dynasty_chains WHERE name = 'Taqali and the Mahdiyya: مملكة تقلي → الدولة المهدية'), 411, 0, NULL, NULL, false, 'The kingdom of Taqali in the Nuba mountains (from ~1570), a hill state that preserved independence from Sennar and from Turco-Egyptian Sudan through tribute diplomacy and mountain warfare.', NULL);
VALUES ((SELECT id FROM dynasty_chains WHERE name = 'Taqali and the Mahdiyya: مملكة تقلي → الدولة المهدية'), 736, 1, 1884, 'CONQUEST', true, 'Mahdist forces invaded Taqali from 1883; Makk Adam was captured in July 1884 and died in Mahdist captivity. Resistance in the hills continued through the Mahdist period.', 'Violent conquest, perpetrator named (Mahdist state). Taqali''s entity record ends 1884 with this conquest.');

-- ── validazione finale ──
DO $$
DECLARE n_ent int; bad int;
BEGIN
  SELECT count(*) INTO n_ent FROM geo_entities WHERE name_original IN (
    'កម្ពុជា (Longvek-Oudong)', 'សាធារណរដ្ឋខ្មែរ', 'Кнежевина Србија', 'Краљевина Срба, Хрвата и Словенаца', 'إمارة الدرعية', 'إمارة نجد', 'सङ्घीय लोकतान्त्रिक गणतन्त्र नेपाल', 'Mthwakazi');
  IF n_ent <> 8 THEN RAISE EXCEPTION 'attese 8 entità nuove, trovate %', n_ent; END IF;
  -- contiguità sequence_order per le catene toccate
  SELECT count(*) INTO bad FROM (
    SELECT chain_id FROM chain_links WHERE chain_id IN (34, 123, 124, 125, 126, 130)
    GROUP BY chain_id
    HAVING count(*) <> max(sequence_order) + 1 OR min(sequence_order) <> 0
  ) t;
  IF bad <> 0 THEN RAISE EXCEPTION 'sequence_order non contigui su % catene', bad; END IF;
  -- ogni link non-primo ha transition_type
  SELECT count(*) INTO bad FROM chain_links WHERE chain_id IN (34, 123, 124, 125, 126, 130)
    AND sequence_order > 0 AND transition_type IS NULL;
  IF bad <> 0 THEN RAISE EXCEPTION '% link non-primi senza transition_type', bad; END IF;
  -- antimeridian guard sui boundary nuovi (CLAUDE.md geometric check)
  SELECT count(*) INTO bad FROM geo_entities WHERE name_original IN (
    'កម្ពុជា (Longvek-Oudong)', 'សាធារណរដ្ឋខ្មែរ', 'Кнежевина Србија', 'Краљевина Срба, Хрвата и Словенаца', 'إمارة الدرعية', 'إمارة نجد', 'सङ्घीय लोकतान्त्रिक गणतन्त्र नेपाल', 'Mthwakazi')
    AND (ST_XMax(boundary_geom) - ST_XMin(boundary_geom)) >= 180;
  IF bad <> 0 THEN RAISE EXCEPTION '% boundary attraversano l''antimeridiano', bad; END IF;
  RAISE NOTICE 'M1 v6.99.120 OK: 11 entità + catene 34/123/124/125/126/130 + 3 nuove';
END $$;

COMMIT;
