INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'កម្ពុជា (Longvek-Oudong)'), 'Camboja', 'pt', 1500, 1700, '16th-17th-century Iberian exonym used by Portuguese and Spanish visitors to Longvek', NULL);
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'កម្ពុជា (Longvek-Oudong)'), 'Cambodge', 'fr', 1863, NULL, 'French exonym, official under the 1863 protectorate', 'Treaty of 11 August 1863');
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'កម្ពុជា (Longvek-Oudong)'), 1431, 'Angkor (Yasodharapura) and northwest heartland', 'CONQUEST_MILITARY', 'Ayutthaya (Siam) captured and sacked the Khmer capital Yasodharapura (Angkor); the royal court shifted south to Chaktomuk (Phnom Penh), founding the Middle Period. Conventional date — the exact nature and year of the Siamese intervention are debated (Vickery 1977), and Angkor''s abandonment was gradual.', NULL, 0.6);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'កម្ពុជា (Longvek-Oudong)'), 1594, 'Longvek (capital, Tonle Sap west bank)', 'CONQUEST_MILITARY', 'King Naresuan of Ayutthaya stormed, looted and destroyed the capital Longvek on 3 January 1594, ending the Siamese-Cambodian War of 1591-1594; population deported, Cambodia reduced to intermittent Siamese vassalage. Court later re-established at Oudong (1618).', NULL, 0.85);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'កម្ពុជា (Longvek-Oudong)'), 1698, 'Kampuchea Krom / Mekong Delta (Prey Nokor-Saigon)', 'CESSION_FORCED', 'The Nguyen lords commissioned Nguyen Huu Canh to organize Prey Nokor (renamed Sai Gon) under Vietnamese administration, de facto detaching it from Cambodia; by 1757 the whole delta (Psar Dek/Sa Dec, Moat Chrouk/Chau Doc) was absorbed into Vietnam, dispossessing the Khmer Krom.', NULL, 0.75);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'កម្ពុជា (Longvek-Oudong)'), 1863, 'Entire kingdom', 'TREATY', 'King Norodom signed the French protectorate treaty on 11 August 1863 under French naval-diplomatic pressure, ending the Siamese-Vietnamese dual vassalage; the monarchy survived but power passed to a French resident. Successor chain leads into French Indochina (federation formed 1887).', NULL, 0.95);
