INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'សាធារណរដ្ឋខ្មែរ'), 'Khmer Republic', 'en', 1970, 1975, 'English name', 'Wikidata Q1054184');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'សាធារណរដ្ឋខ្មែរ'), 'Sathearonaroat Khmae', 'km-Latn', 1970, 1975, 'romanization of សាធារណរដ្ឋខ្មែរ', 'en.wikipedia.org/wiki/Khmer_Republic');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'សាធារណរដ្ឋខ្មែរ'), 'République khmère', 'fr', 1970, 1975, 'official name in French, co-official language of the republic', 'en.wikipedia.org/wiki/Khmer_Republic');
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'សាធារណរដ្ឋខ្មែរ'), 1970, 'Phnom Penh / nationwide', 'REVOLUTION', '18 March 1970: National Assembly vote led by Prime Minister Lon Nol and Sisowath Sirik Matak deposed head of state Norodom Sihanouk while he was abroad; the monarchy was abolished and the Khmer Republic formally proclaimed on 9 October 1970. Sihanouk formed the GRUNK government-in-exile allied with the Khmer Rouge, starting full-scale civil war.', NULL, 0.9);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'សាធារណរដ្ឋខ្មែរ'), 1970, 'Phnom Penh and Mekong lowlands', 'ETHNIC_CLEANSING', 'April 1970: pogroms against Cambodia''s c. 400,000-strong ethnic Vietnamese minority, organized and tolerated by the Lon Nol government — army and police rounded up, interned and massacred thousands of civilians (bodies floated down the Mekong into South Vietnam); most of the surviving community fled or was expelled to South Vietnam.', NULL, 0.8);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'សាធារណរដ្ឋខ្មែរ'), 1973, 'rural Cambodia (countryside)', 'CONQUEST_MILITARY', 'By the US Congress-mandated bombing halt of 15 August 1973 (end of Operation Freedom Deal), CPK/Khmer Rouge and GRUNK forces controlled most of the countryside; the Republic was reduced to Phnom Penh, provincial capitals and supply corridors. US bombing 1969-73 killed an estimated 50,000-150,000 Cambodian civilians (Kiernan & Owen; disputed range).', NULL, 0.75);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'សាធារណរដ្ឋខ្មែរ'), 1975, 'Phnom Penh', 'CONQUEST_MILITARY', '17 April 1975: the Khmer Rouge captured Phnom Penh after a siege; the Khmer Republic collapsed and was succeeded by the CPK regime (Democratic Kampuchea). The last government outpost, Preah Vihear temple, fell on 22 May 1975.', NULL, 0.9);
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'សាធារណរដ្ឋខ្មែរ'), 'William Shawcross, Sideshow: Kissinger, Nixon and the Destruction of Cambodia, Simon & Schuster, 1979 (rev. ed. Cooper Square Press, 2002)', 'https://books.google.com/books/about/Sideshow.html?id=bjtvQgAACAAJ', 'secondary');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
