INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'សាធារណរដ្ឋខ្មែរ'), 'Justin J. Corfield, Khmers Stand Up! A History of the Cambodian Government 1970-1975, Monash Papers on Southeast Asia No. 32, Centre of Southeast Asian Studies, Monash University, 1994', 'https://catalogue.nla.gov.au/catalog/662024', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
