INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Кнежевина Србија'), 'Kingdom of Serbia', 'en', 1882, 1918, 'English exonym, kingdom phase', NULL);
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Кнежевина Србија'), 'Principauté de Serbie', 'fr', 1830, 1882, 'French, diplomatic language of the era (Treaty of Berlin drafted in French)', 'Treaty of Berlin, 1878');
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Кнежевина Србија'), 1815, 'Pashalik of Belgrade (Sumadija / Morava valley core)', 'REVOLUTION', 'Second Serbian Uprising under Milos Obrenovic (from April 1815, Takovo); negotiated settlement with Marashli Ali Pasha gave Serbs de facto self-rule within the Pashalik of Belgrade while remaining under Ottoman suzerainty.', NULL, 0.95);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Кнежевина Србија'), 1830, 'Autonomous Principality (Belgrade pashalik core)', 'TREATY', 'Ottoman hatt-i sharif of 1830 (following the Akkerman Convention 1826 and Treaty of Adrianople 1829) recognized Serbia as an autonomous, tribute-paying hereditary principality under Milos Obrenovic; Ottoman garrisons remained in the fortress towns.', NULL, 0.95);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Кнежевина Србија'), 1833, 'Six nahiyes (Krajina, Crna Reka, Banja/Aleksinac, Krusevac, Stari Vlah, Jadar-Radjevina)', 'TREATY', 'Supplementary hatt-i sharif of 1833 confirmed the annexation of six contested nahiyes claimed since the First Uprising, enlarging the principality to its 1833-1878 extent.', NULL, 0.85);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Кнежевина Србија'), 1862, 'Belgrade and Serbian fortress towns', 'ETHNIC_CLEANSING', 'Cukur Fountain incident: Ottoman soldiers killed a Serb apprentice boy; riots followed and the Ottoman garrison bombarded civilian Belgrade from the fortress (~50 killed). The Great-Power Kanlica conference then mandated the departure of the Muslim civilian population from Serbian towns; roughly 10,000 Muslims left the six Serbian garrison towns in the 1862-1867 wave (about 2,100 of them from Belgrade). Dual agency: Ottoman garrison (bombardment); Serbian state and Great Powers (sanctioned population removal).', NULL, 0.8);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Кнежевина Србија'), 1867, 'Fortresses of Belgrade, Sabac, Smederevo, Kladovo', 'TREATY', 'Ottoman garrisons withdrew from all remaining fortresses; keys of Belgrade fortress ceremonially handed to Prince Mihailo Obrenovic on Kalemegdan (April 1867), ending the Ottoman military presence while nominal suzerainty continued.', NULL, 0.95);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Кнежевина Србија'), 1878, 'Nis, Pirot, Toplica and Vranje districts', 'TREATY', 'Treaty of Berlin (13 July 1878) recognized Serbia''s full independence from the Ottoman Empire and its annexation of four southeastern districts (Nis, Pirot, Toplica, Vranje) taken in the 1876-78 Serbo-Ottoman wars.', NULL, 0.95);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Кнежевина Србија'), 1878, 'Nis and Toplica sanjaks (newly annexed districts)', 'ETHNIC_CLEANSING', 'During and after the 1877-78 war the Serbian army under Prince Milan Obrenovic expelled the Muslim population of the annexed regions — majority Albanian in the countryside, Turkish in the towns, about one third of the regional population. Academic estimates: ~49,000 Albanians among at least 71,000 Muslims expelled or fled without return (Jagodic 1998; Stefanovic 2005); Albanian historiography cites higher figures. Refugees (muhaxhire) resettled largely in Ottoman Kosovo.', NULL, 0.8);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Кнежевина Србија'), 1912, 'Kosovo and Vardar Macedonia', 'CONQUEST_MILITARY', 'First Balkan War (October-November 1912): Serbian army conquered Kosovo and Vardar Macedonia from the Ottoman Empire. The Carnegie Endowment''s 1914 International Commission documented massacres of Albanian civilians, village burnings and forced conversions by Serbian forces, alongside grave violations by all belligerents. Albanian and Macedonian populations passed under Serbian military rule without consent.', NULL, 0.9);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Кнежевина Србија'), 1913, 'Kosovo, Vardar Macedonia, eastern Sandzak of Novi Pazar', 'TREATY', 'Treaties of London (May 1913) and Bucharest (August 1913) after the Second Balkan War confirmed Serbia''s possession of Kosovo, most of Vardar Macedonia (disputed with Bulgaria) and the eastern Sandzak (partitioned with Montenegro), nearly doubling the state''s territory. Rule remained contested and militarized until 1915.', NULL, 0.9);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Кнежевина Србија'), 1915, 'Entire state territory', 'CONQUEST_MILITARY', 'TERRITORIAL LOSS: combined Austro-Hungarian, German and Bulgarian offensive (October-November 1915) conquered all of Serbia; the country was partitioned into Austro-Hungarian and Bulgarian occupation zones (internment, forced Bulgarianization, bloody suppression of the 1917 Toplica uprising). The Serbian army and tens of thousands of civilians retreated through the Albanian mountains in winter 1915-16 with mass deaths from cold, hunger and disease; the army was evacuated to Corfu.', NULL, 0.95);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Кнежевина Србија'), 1918, 'Entire state territory', 'LIBERATION', 'Salonika front breakthrough (September 1918) led to the liberation of Serbia by Serbian and Allied forces (Belgrade retaken 1 November 1918). On 1 December 1918 the Kingdom of Serbia merged into the newly proclaimed Kingdom of Serbs, Croats and Slovenes, ending its separate statehood. Serbia''s WWI losses were among the highest per-capita of any belligerent (16-28% of pre-war population depending on methodology).', NULL, 0.95);
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Кнежевина Србија'), 'Jagodic, Milos. ''The Emigration of Muslims from the New Serbian Regions 1877/1878''. Balkanologie, Vol. II, no. 2 (1998).', 'https://journals.openedition.org/balkanologie/265', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
