INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Кнежевина Србија'), 'Jelavich, Barbara. History of the Balkans: Eighteenth and Nineteenth Centuries (Vol. 1) and Twentieth Century (Vol. 2). Cambridge: Cambridge University Press, 1983.', NULL, 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Кнежевина Србија'), 'Hatt-i Sharif of 1830 (Ottoman imperial decree recognizing the autonomous hereditary Principality of Serbia) and Treaty of Berlin, 13 July 1878, Articles XXXIV-XLII (independence and borders of Serbia).', NULL, 'primary');
INSERT INTO geo_entities (name_original, name_original_lang, entity_type, year_start, year_end,
