INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Краљевина Срба, Хрвата и Словенаца'), 'Kingdom of Serbs, Croats and Slovenes', 'en', 1918, 1929, 'English name of the founding period', 'Banac 1984; Lampe 2000');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Краљевина Срба, Хрвата и Словенаца'), 'Краљевство Срба, Хрвата и Словенаца', 'sr', 1918, 1920, 'Form used in the 1 December 1918 unification proclamation (''Kraljevstvo''); changed to ''Kraljevina'' by decision of the Provisional National Representation on 15 July 1920', 'Srpska enciklopedija; sr.wikipedia');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Краљевина Срба, Хрвата и Словенаца'), 'Краљевина Југославија', 'sr', 1929, 1941, 'Official name from 3 October 1929 (royal decree of Aleksandar I)', 'Wikidata Q191077 (verified); Djokić 2007');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Краљевина Срба, Хрвата и Словенаца'), 'Kraljevina Jugoslavija', 'sh', 1929, 1941, 'Latin-script form (identical in Slovene)', 'sr.wikipedia');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Краљевина Срба, Хрвата и Словенаца'), 'Kingdom of Yugoslavia', 'en', 1929, 1941, 'English name after the 1929 renaming', 'Lampe 2000; Tomasevich 2001');
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Краљевина Срба, Хрвата и Словенаца'), 1918, 'Montenegro', 'CESSION_FORCED', 'The Podgorica Assembly (in session 24-29 November 1918), convened under Serbian army presence with an irregular electoral procedure, deposed King Nikola I Petrović-Njegoš and proclaimed unconditional union with Serbia. The Greens'' Christmas Uprising against the annexation (Cetinje, 7 January 1919, led by Krsto Popović) was crushed by Serbian troops and pro-union White militias; guerrilla resistance and reprisals continued into the mid-1920s. Montenegrin and part of Western historiography (Pavlović 2008) call this an annexation; Serbian unification historiography calls it a voluntary union.', NULL, 0.8);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Краљевина Срба, Хрвата и Словенаца'), 1918, 'All South Slav lands (Serbia, Montenegro, former Habsburg South Slav territories)', 'TREATY', '1 December 1918: Regent Aleksandar Karađorđević proclaimed the Kingdom of Serbs, Croats and Slovenes, uniting the Kingdom of Serbia (with newly absorbed Montenegro) and the State of Slovenes, Croats and Serbs formed from the collapsed Austria-Hungary — a negotiated unification (Corfu Declaration 1917, National Council address), not a treaty in the strict sense.', NULL, 0.9);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Краљевина Срба, Хрвата и Словенаца'), 1920, 'Istria, Zadar and Adriatic islands', 'TREATY', 'Treaty of Rapallo (12 November 1920): the Kingdom ceded Istria, Zadar and several islands to Italy; roughly half a million South Slavs (Slovenes, Croats) came under Italian rule and subsequent forced Italianization. Rijeka went to Italy by the 1924 Treaty of Rome, with Sušak remaining Yugoslav.', NULL, 0.85);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Краљевина Срба, Хрвата и Словенаца'), 1941, 'Entire kingdom', 'CONQUEST_MILITARY', 'Axis invasion from 6 April 1941, opened by Nazi Germany''s terror bombing of Belgrade that killed thousands of civilians; unconditional surrender on 17 April 1941. Nazi Germany, Fascist Italy, Hungary and Bulgaria partitioned the country, installing the Ustaša-run Independent State of Croatia (10 April 1941), occupied Serbia, the Italian Governorate of Montenegro and the Province of Ljubljana.', NULL, 0.9);
