  ((SELECT id FROM geo_entities WHERE name_original = 'Краљевина Срба, Хрвата и Словенаца'), 'Dejan Djokić, Elusive Compromise: A History of Interwar Yugoslavia, Hurst / Columbia University Press, 2007.', 'https://muse.jhu.edu/article/817674/summary', 'academic');
