INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة الدرعية'), 'الدولة السعودية الأولى', 'ar', NULL, NULL, 'ad-Dawla as-Suʿūdiyya al-ʾŪlā — retrospective official Arabic designation used in Saudi historiography and state commemoration', 'Wikidata Q146871 Arabic label; Saudipedia');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة الدرعية'), 'ad-Dawla as-Suʿūdiyya al-ʾŪlā', 'ar-Latn', NULL, NULL, 'Romanization of the retrospective Arabic designation', 'Wikipedia');
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة الدرعية'), 1744, 'Diriyah (central Najd)', 'TREATY', 'Pact between Emir Muhammad ibn Saud (ruler of Diriyah since 1727) and the preacher Muhammad ibn Abd al-Wahhab fused Al Saud political power with the Wahhabi religious mission, founding the expansionist emirate.', NULL, 0.85);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة الدرعية'), 1773, 'Riyadh and Najd', 'CONQUEST_MILITARY', 'Abdulaziz bin Muhammad captured Riyadh after a long war against Dahham ibn Dawwas, consolidating Saudi-Wahhabi military control over central Najd; al-Hasa on the Gulf coast followed by 1795.', NULL, 0.8);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة الدرعية'), 1803, 'Hejaz (Taif, Mecca; Medina 1804-05)', 'CONQUEST_MILITARY', 'Saudi forces under Saud bin Abdulaziz took Taif (with a massacre of inhabitants), then Mecca in 1803 and Medina by 1804-05; in 1806 they demolished the domed tombs of al-Baqi cemetery in Medina and Jannat al-Mualla in Mecca (including the tomb of Khadijah) as idolatrous. The 21 April 1802 sack of Shia Karbala (2,000-5,000 killed, shrine of Imam Husayn plundered) preceded this campaign.', NULL, 0.75);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة الدرعية'), 1818, 'Diriyah and all Saudi territories', 'CONQUEST_MILITARY', 'Ottoman-Egyptian army under Ibrahim Pasha, son of Muhammad Ali of Egypt, ended the Ottoman-Saudi (Wahhabi) War of 1811-1818: after a months-long siege, Imam Abdullah bin Saud surrendered on 9 September 1818; Diriyah was razed in 1819 and Abdullah was beheaded in Istanbul.', NULL, 0.85);
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة الدرعية'), 'Madawi Al-Rasheed, A History of Saudi Arabia, Cambridge University Press, 2002 (2nd ed. 2010)', 'https://www.cambridge.org/core/books/history-of-saudi-arabia/3B0C42E92B2A83F79E85D28083D2D223', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة الدرعية'), 'Alexei Vassiliev, The History of Saudi Arabia, Saqi Books, London, 1998 (US ed. New York University Press, 2000)', 'https://search.worldcat.org/title/39641842', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة الدرعية'), 'George S. Rentz, The Birth of the Islamic Reform Movement in Saudi Arabia: Muhammad ibn ''Abd al-Wahhab (1703/4-1792) and the Beginnings of Unitarian Empire in Arabia, Arabian Publishing, London, 2004', 'https://arabian-publishing.com/product/the-birth-of-the-islamic-reform-movement-in-saudi-arabia', 'academic');
