INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة نجد'), 'Emirate of Nejd', 'en', 1824, 1891, 'alternative English spelling', NULL);
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة نجد'), 'Second Saudi State', 'en', NULL, NULL, 'retrospective historiographic name (ETHICS-001: modern Saudi periodization, not contemporary usage)', 'Madawi al-Rasheed, A History of Saudi Arabia (2002)');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة نجد'), 'الدولة السعودية الثانية', 'ar', NULL, NULL, 'al-Dawla al-Su''udiyya al-Thaniya — retrospective Arabic historiographic name', 'ar.wikipedia.org; saudipedia.com');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة نجد'), 'Imārat Najd', 'ar-Latn', 1824, 1891, 'romanization of the primary name', NULL);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة نجد'), 1824, 'Riyadh and central Najd', 'CONQUEST_MILITARY', 'Turki ibn Abdullah Al Saud besieged and expelled the Egyptian garrison (Muhammad Ali''s occupation forces) from Riyadh, restoring Al Saud rule six years after the Ottoman-Egyptian destruction of Diriyah; Riyadh made the new capital.', NULL, 0.85);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة نجد'), 1830, 'al-Hasa and Qatif (Eastern Arabia)', 'CONQUEST_MILITARY', 'Turki ibn Abdullah reconquered al-Hasa, Qatif and Saihat, extending Saudi rule to the Gulf coast; the region''s Shia population became tributary subjects of the Wahhabi-legitimated state.', NULL, 0.75);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة نجد'), 1871, 'al-Hasa and Qatif', 'CONQUEST_MILITARY', 'Ottoman al-Hasa Expedition under Baghdad governor Midhat Pasha: invited by Imam Abdullah bin Faisal against his brother Saud during the Saudi civil war, the Ottomans instead annexed al-Hasa outright (held until 1913), stripping the emirate of its eastern province.', NULL, 0.85);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة نجد'), 1891, 'Najd (entire state)', 'CONQUEST_MILITARY', 'Battle of Mulayda (21 January 1891): Muhammad bin Abdullah Al Rashid of the Emirate of Jabal Shammar defeated the last imam Abdul Rahman bin Faisal; the state ceased to exist and the Al Saud went into exile in Kuwait.', NULL, 0.9);
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة نجد'), 'R. Bayly Winder, Saudi Arabia in the Nineteenth Century, London: Macmillan / New York: St. Martin''s Press, 1965 (xiv+312 pp.) — the standard monograph on the second Saudi state.', 'https://link.springer.com/book/10.1007/978-1-349-81723-8', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة نجد'), 'Madawi al-Rasheed, A History of Saudi Arabia, Cambridge: Cambridge University Press, 2002 (2nd ed. 2010) — history by a Saudi-born scholar, critical of official dynastic narratives.', 'https://www.cambridge.org/core/books/history-of-saudi-arabia/1C499DA74EC7147305236A70C1F7C7DB', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة نجد'), 'Alexei Vassiliev, The History of Saudi Arabia, London: Saqi Books, 1998 (576 pp., ISBN 0-86356-935-8) — Russian-school historiography drawing on Arabic, Turkish and Russian sources.', 'https://saqibooks.com/books/saqi/the-history-of-saudi-arabia/', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'إمارة نجد'), 'ʿUthmān ibn ʿAbd Allāh Ibn Bishr, ʿUnwān al-majd fī tārīkh Najd [The Sign of Glory in the History of Najd], vol. 2 completed 1270 AH / 1853-54 CE — contemporary Najdi chronicle covering the first and second Saudi states to 1854.', 'https://onlinebooks.library.upenn.edu/webbin/book/lookupid?key=ha001866084', 'primary');
INSERT INTO geo_entities (name_original, name_original_lang, entity_type, year_start, year_end,
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'सङ्घीय लोकतान्त्रिक गणतन्त्र नेपाल'), 'Federal Democratic Republic of Nepal', 'en', 2008, NULL, 'Official English long-form name since the 28 May 2008 republic declaration', 'Wikidata Q837; Constituent Assembly declaration 2008');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'सङ्घीय लोकतान्त्रिक गणतन्त्र नेपाल'), 'Saṅghīya Loktāntrik Gaṇatantra Nepāl', 'ne-Latn', 2008, NULL, 'IAST-style romanization of the Nepali official name', 'Romanization of attested Devanagari form');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'सङ्घीय लोकतान्त्रिक गणतन्त्र नेपाल'), 'नेपाल', 'ne', 2015, NULL, 'Constitutional short name: Constitution of Nepal 2015, Art. 4, names the state ''Nepal''; a Nov 2020 government directive limited letterhead use of the full republican formula', 'Constitution of Nepal 2015 (Nepal Law Commission)');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'सङ्घीय लोकतान्त्रिक गणतन्त्र नेपाल'), 'Nepal', 'en', 2008, NULL, 'Common short name', 'Wikidata Q837');
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'सङ्घीय लोकतान्त्रिक गणतन्त्र नेपाल'), 2008, 'Entire state (former Kingdom of Nepal)', 'REVOLUTION', 'On 28 May 2008 the 1st Constituent Assembly, elected on 10 April 2008 under the Comprehensive Peace Accord (21 Nov 2006), abolished the 240-year Shah monarchy by a 560-4 vote and declared the Federal Democratic Republic. The peaceful vote was the direct outcome of the 1996-2006 Maoist civil war (~13,000-17,000 dead; state forces the larger documented killer) and the April 2006 Jana Andolan II mass uprising, in which royal security forces killed ~18-25 protesters before King Gyanendra capitulated.', NULL, 0.9);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'सङ्घीय लोकतान्त्रिक गणतन्त्र नेपाल'), 2020, 'Kalapani-Lipulekh-Limpiyadhura (far-west, ~335-372 km2)', 'UNKNOWN', 'Constitutional amendment (June 2020) added the India-administered Kalapani-Lipulekh-Limpiyadhura triangle to Nepal''s official map and coat of arms. This is a cartographic-legal claim only: India continues to administer the territory and rejects the claim. No change of actual control occurred; the dispute remains open.', NULL, 0.75);
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'सङ्घीय लोकतान्त्रिक गणतन्त्र नेपाल'), 'John Whelpton, A History of Nepal, Cambridge University Press, 2005.', 'https://www.cambridge.org/core/books/history-of-nepal/340C4E78125368B8D0623201D61E5A9E', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'सङ्घीय लोकतान्त्रिक गणतन्त्र नेपाल'), 'Sebastian von Einsiedel, David M. Malone and Suman Pradhan (eds.), Nepal in Transition: From People''s War to Fragile Peace, Cambridge University Press, 2012.', 'https://www.cambridge.org/core/books/nepal-in-transition/FAA071F9BDF58C731109296F59C86F4A', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'सङ्घीय लोकतान्त्रिक गणतन्त्र नेपाल'), 'Prashant Jha, Battles of the New Republic: A Contemporary History of Nepal, Hurst & Company, 2014. (Nepali/South Asian author — non-Western historiography per ETHICS values)', 'https://www.hurstpublishers.com/book/battles-new-republic/', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'सङ्घीय लोकतान्त्रिक गणतन्त्र नेपाल'), 'OHCHR, Nepal Conflict Report: An analysis of conflict-related violations of international human rights law and international humanitarian law between February 1996 and 21 November 2006, United Nations Office of the High Commissioner for Human Rights, 2012.', 'https://www.ohchr.org/en/documents/country-reports/nepal-conflict-report', 'primary');
