INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'सङ्घीय लोकतान्त्रिक गणतन्त्र नेपाल'), 'Human Rights Watch, "Like We Are Not Nepali": Protest and Police Crackdown in the Terai Region of Nepal, HRW, 2015.', 'https://www.hrw.org/report/2015/10/16/we-are-not-nepali/protest-and-police-crackdown-terai-region-nepal', 'primary');
INSERT INTO geo_entities (name_original, name_original_lang, entity_type, year_start, year_end,
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Mthwakazi'), 'Mthwakazi', 'nd', 1838, NULL, 'Attested endonym; per Ndebele tradition the name Mzilikazi gave his nation (''something which became big at conception''). Latin script is native for isiNdebele.', 'Wikidata Q1193853; Ndlovu-Gatsheni, The Ndebele Nation (2009)');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Mthwakazi'), 'Ndebele Kingdom', 'en', NULL, NULL, 'Modern English scholarly name (also ''Northern Ndebele Kingdom'' to distinguish from the Southern/Transvaal Ndebele)', 'Rasmussen 1978; Cobbing 1976');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Mthwakazi'), 'Matabele Kingdom', 'en', 1838, 1893, '19th-century British colonial name, from the Sotho-Tswana exonym ''Matebele'' transmitted to British travellers; not the endonym', 'Wikipedia, Northern Ndebele people');
INSERT INTO name_variants (entity_id, name, lang, period_start, period_end, context, source) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Mthwakazi'), 'Matabeleland', 'en', 1838, NULL, 'British name for the territory; retained as a Rhodesian and then Zimbabwean regional name after the conquest', 'Wikidata Q1266775 (modern region)');
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Mthwakazi'), 1838, 'Matabeleland highveld (southwestern Zimbabwean plateau)', 'CONQUEST_MILITARY', 'After defeats by Voortrekker commandos in the Transvaal (Vegkop 1836, Mosega/eGabeni 1837), Mzilikazi''s Khumalo-led Ndebele crossed the Limpopo and settled the southwestern Zimbabwean plateau (c. 1838-1840), displacing and forcibly incorporating local Kalanga and Rozvi-Shona communities.', NULL, 0.75);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Mthwakazi'), 1840, 'Former Rozvi heartland (Danamombe, Insiza-Mberengwa belt)', 'CONQUEST_MILITARY', 'Ndebele forces defeated the Rozvi Mutinhima house; the remaining Rozvi royal houses, leaderless since Nyamazana''s Ngoni sacked Danamombe and killed Changamire Chirisamhuru c. 1835, submitted one by one c. 1839-1840 and were reduced to tributary status.', NULL, 0.6);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Mthwakazi'), 1888, 'Mineral rights over Matabeleland, Mashonaland and adjoining territories', 'TREATY', 'Rudd Concession (30 Oct 1888): Lobengula granted exclusive mineral rights to Cecil Rhodes''s agents Charles Rudd, Rochfort Maguire and Francis Thompson for 100 pounds per lunar month, 1,000 Martini-Henry rifles, 100,000 cartridges and a Zambezi steamboat. Interpreter Charles Helm''s mistranslation and the exclusion of verbal assurances (max ten diggers, subject to Ndebele law) from the written English text made it fraudulent; Lobengula repudiated it and protested to Queen Victoria without effect. It became the legal basis of the British South Africa Company''s royal charter (Oct 1889) and the 1890 Pioneer Column occupation of Mashonaland.', NULL, 0.85);
INSERT INTO territory_changes (entity_id, year, region, change_type, description, population_affected, confidence_score) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Mthwakazi'), 1893, 'Entire kingdom', 'CONQUEST_MILITARY', 'First Matabele War: British South Africa Company columns using Maxim guns killed roughly 1,500 Ndebele at the Shangani (25 Oct 1893) and about 2,500 at Bembesi (1 Nov 1893) against single-digit company battle deaths; Lobengula burned koBulawayo and fled north; the BSAC occupied Bulawayo on 4 Nov 1893 and seized Ndebele land and cattle. Lobengula died in flight, probably of smallpox, on 22/23 Jan 1894.', NULL, 0.85);
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
  ((SELECT id FROM geo_entities WHERE name_original = 'Mthwakazi'), 'R. Kent Rasmussen, Migrant Kingdom: Mzilikazi''s Ndebele in South Africa, London: Rex Collings / Cape Town: David Philip, 1978', 'https://books.google.com/books/about/Migrant_Kingdom.html?id=M2QfAAAAMAAJ', 'academic');
INSERT INTO sources (entity_id, citation, url, source_type) VALUES
